package com.bank.scaling.instance;

import java.util.logging.Logger;

// One instance with a bounded requests-per-second capacity.
public class ServerInstance {
    private static final Logger log = Logger.getLogger(ServerInstance.class.getName());
    private final String id;
    private int capacityRps;       // how much this ONE instance can handle
    private boolean healthy = true;

    public ServerInstance(String id, int capacityRps) {
        this.id = id;
        this.capacityRps = capacityRps;
    }

    public String getId() { return id; }
    public int getCapacityRps() { return capacityRps; }
    public boolean isHealthy() { return healthy; }
    public void crash() { healthy = false; log.severe(() -> "INSTANCE " + id + " crashed"); }

    // Vertical scaling changes THIS instance's capacity.
    public void resizeTo(int newCapacity) {
        log.warning(() -> "VERTICAL resize " + id + ": " + capacityRps + " -> " + newCapacity
                + " rps (requires restart = downtime)");
        this.capacityRps = newCapacity;
    }
}
