package com.bank.scaling.vertical;

import com.bank.scaling.instance.ServerInstance;
import java.util.logging.Logger;

// Scale UP a single instance, but there is a hard hardware ceiling.
public class VerticalScaler {
    private static final Logger log = Logger.getLogger(VerticalScaler.class.getName());
    private final ServerInstance instance;
    private final int maxPossibleRps;   // biggest machine you can buy

    public VerticalScaler(ServerInstance instance, int maxPossibleRps) {
        this.instance = instance;
        this.maxPossibleRps = maxPossibleRps;
    }

    // Returns true if it could satisfy the demand, false if it hit the ceiling.
    public boolean scaleUpToHandle(int demandRps) {
        int target = Math.min(demandRps, maxPossibleRps);
        instance.resizeTo(target);
        if (demandRps > maxPossibleRps) {
            log.severe(() -> "VERTICAL CEILING hit: demand " + demandRps
                    + " > max machine " + maxPossibleRps + " rps — cannot scale further");
            return false;
        }
        return true;
    }
}
