package com.bank.scaling.horizontal;

import com.bank.scaling.instance.ServerInstance;
import java.util.List;
import java.util.stream.Collectors;

// Distributes total load across all HEALTHY instances.
public class LoadBalancer {
    // Total capacity is the sum of healthy instances' capacities.
    public int totalCapacity(List<ServerInstance> instances) {
        return instances.stream()
                .filter(ServerInstance::isHealthy)
                .mapToInt(ServerInstance::getCapacityRps)
                .sum();
    }

    public List<ServerInstance> healthy(List<ServerInstance> instances) {
        return instances.stream().filter(ServerInstance::isHealthy).collect(Collectors.toList());
    }
}
