package com.bank.scaling.horizontal;

import com.bank.scaling.instance.ServerInstance;
import java.util.*;
import java.util.logging.Logger;

// Scale OUT: add identical instances until total capacity meets demand.
public class HorizontalScaler {
    private static final Logger log = Logger.getLogger(HorizontalScaler.class.getName());
    private final int perInstanceRps;
    private final LoadBalancer lb = new LoadBalancer();
    private final List<ServerInstance> instances = new ArrayList<>();
    private int seq = 0;

    public HorizontalScaler(int perInstanceRps) { this.perInstanceRps = perInstanceRps; }

    public List<ServerInstance> getInstances() { return instances; }

    // Add identical instances until total capacity >= demand.
    public void scaleOutToHandle(int demandRps) {
        while (lb.totalCapacity(instances) < demandRps) {
            ServerInstance inst = new ServerInstance("txn-" + (++seq), perInstanceRps);
            instances.add(inst);
            log.info(() -> "HORIZONTAL add " + inst.getId() + " (+ " + perInstanceRps
                    + " rps); total now " + lb.totalCapacity(instances) + " rps");
        }
        log.info(() -> "Demand " + demandRps + " rps met with "
                + lb.healthy(instances).size() + " instances (no downtime)");
    }

    public int currentCapacity() { return lb.totalCapacity(instances); }
    public int healthyCount() { return lb.healthy(instances).size(); }
}
