package com.bank.scaling;

import com.bank.scaling.horizontal.HorizontalScaler;
import com.bank.scaling.instance.ServerInstance;
import com.bank.scaling.vertical.VerticalScaler;
import java.util.logging.*;

public class ScalingDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(ScalingDemo.class.getName());

        // VERTICAL: one instance, grow it — until the ceiling.
        log.info("=== Vertical scaling (scale up) ===");
        ServerInstance single = new ServerInstance("txn-big", 500);
        VerticalScaler vertical = new VerticalScaler(single, 4000); // max machine 4000 rps
        vertical.scaleUpToHandle(1500);   // ok
        vertical.scaleUpToHandle(4000);   // at ceiling
        boolean canGoHigher = vertical.scaleUpToHandle(8000); // exceeds ceiling
        log.info("Could vertical scaling meet 8000 rps? " + canGoHigher);
        single.crash();  // single point of failure -> total outage
        log.severe("With one instance, the crash = total outage");

        // HORIZONTAL: add identical instances, survive a crash.
        log.info("=== Horizontal scaling (scale out) ===");
        HorizontalScaler horizontal = new HorizontalScaler(500); // 500 rps each
        horizontal.scaleOutToHandle(8000);   // meets 8000 with 16 instances, no downtime
        log.info("Capacity=" + horizontal.currentCapacity()
                + " rps with " + horizontal.healthyCount() + " instances");

        // One instance crashes: capacity dips, service survives.
        horizontal.getInstances().get(0).crash();
        log.warning("One instance crashed; capacity now " + horizontal.currentCapacity()
                + " rps with " + horizontal.healthyCount() + " healthy (service still UP)");
    }
}

